begin;
create temporary table p9_before as select(select count(*)from public.financial_payments)payments,(select count(*)from public.financial_refunds)refunds,(select count(*)from public.financial_settlements)settlements,(select count(*)from public.financial_settlement_items)items,(select count(*)from public.account_moves where state='posted')moves,(select count(*)from public.account_move_lines where parent_state='posted')lines,(select count(*)from public.account_partial_reconcile)partials,(select coalesce(sum(debit),0)from public.account_move_lines where parent_state='posted')debit,(select coalesce(sum(credit),0)from public.account_move_lines where parent_state='posted')credit;
create temporary table p9_context as select o.tenant_id,o.id owner_id,o.auth_user_id owner_auth,u.id other_id,u.auth_user_id other_auth from public.tenant_users o join lateral(select x.*from public.tenant_users x where x.tenant_id=o.tenant_id and x.is_active and x.role<>'owner'and x.auth_user_id is not null limit 1)u on true where o.role='owner'and o.is_active and o.auth_user_id is not null limit 1;
do $$begin if not exists(select 1 from p9_context)then raise exception'PHASE9_FIXTURE_UNAVAILABLE';end if;end$$;
create temporary table p9_r(branch uuid,customer uuid,method uuid,config uuid,bank_destination uuid,bank_account uuid,clearing uuid,fee uuid,ar uuid,revenue uuid,clearing_journal uuid,p1 uuid,l1 uuid,p2 uuid,l2 uuid,p3 uuid,l3 uuid,p4 uuid,l4 uuid,p5 uuid,l5 uuid,invoice_line uuid,reversal_target uuid);
grant select on p9_context to public;grant select,update on p9_r to public;
grant insert on public.account_moves,public.account_move_lines to authenticated;
do $$declare c p9_context%rowtype;r p9_r%rowtype;g uuid;s text:=left(replace(gen_random_uuid()::text,'-',''),8);gid uuid;begin select*into c from p9_context;select id into g from public.account_groups where tenant_id=c.tenant_id limit 1;r.branch:=gen_random_uuid();insert into public.branches(id,tenant_id,name,code,is_active)values(r.branch,c.tenant_id,'Phase9 Branch','P9'||left(s,5),true);insert into public.partners(tenant_id,name,contact_type,is_company,is_external_contact,customer_rank,supplier_rank,financer_rank,active)values(c.tenant_id,'P9 Customer','person',false,true,1,0,0,true)returning id into r.customer;
 insert into public.financial_payment_methods(tenant_id,name,semantic_key,method_type,requires_reference,requires_confirmation,created_by)values(c.tenant_id,'P9 Card','p9_card_'||s,'card',true,true,c.owner_id)returning id into r.method;
 insert into public.account_accounts(tenant_id,group_id,code,name,account_type,reconcile,active,canonical_account_type,statement_section,reporting_category,normal_balance,open_item_reconcile,statement_reconcile,is_posting,semantic_key,template_account_key,account_origin)values(c.tenant_id,g,'P9CL'||s,'P9 Provider Clearing','asset',true,true,'current_asset','balance_sheet','other_receivables','debit',true,false,true,'p9_clearing_'||s,'p9_clearing_'||s,'template')returning id into r.clearing;
 insert into public.account_accounts(tenant_id,group_id,code,name,account_type,reconcile,active,canonical_account_type,statement_section,reporting_category,normal_balance,pnl_category,open_item_reconcile,statement_reconcile,is_posting,semantic_key,template_account_key,account_origin)values(c.tenant_id,g,'P9FE'||s,'P9 Processing Fees','expense',false,true,'expense','profit_and_loss','operating_expenses','debit','operating',false,false,true,'p9_fee_'||s,'p9_fee_'||s,'template')returning id into r.fee;
 insert into public.account_accounts(tenant_id,group_id,code,name,account_type,reconcile,active,canonical_account_type,statement_section,reporting_category,normal_balance,open_item_reconcile,statement_reconcile,is_posting,semantic_key,template_account_key,account_origin)values(c.tenant_id,g,'P9AR'||s,'P9 AR','asset',true,true,'receivable','balance_sheet','trade_receivables','debit',true,false,true,'trade_receivable','p9_ar_'||s,'template')returning id into r.ar;
 insert into public.account_accounts(tenant_id,group_id,code,name,account_type,reconcile,active,canonical_account_type,statement_section,reporting_category,normal_balance,pnl_category,open_item_reconcile,statement_reconcile,is_posting,semantic_key,template_account_key,account_origin)values(c.tenant_id,g,'P9RV'||s,'P9 Revenue','income',false,true,'income','profit_and_loss','revenue','credit','operating',false,false,true,'p9_revenue_'||s,'p9_revenue_'||s,'template')returning id into r.revenue;
 insert into public.account_journals(tenant_id,code,name,type,default_account_id,branch_id,is_active)values(c.tenant_id,'P9'||left(s,4),'P9 Clearing','general',r.clearing,r.branch,true)returning id into r.clearing_journal;update public.account_functional_accounts set is_active=false where tenant_id=c.tenant_id and functional_role='customer_receivable'and is_active;insert into public.account_functional_accounts(tenant_id,functional_role,account_id)values(c.tenant_id,'customer_receivable',r.ar);
 insert into public.res_groups(tenant_id,name,code,category,is_system,active)values(c.tenant_id,'P9 actors','p9_'||s,'Tenant',false,true)returning id into gid;insert into public.auth_group_permissions(group_id,permission_id)select gid,id from public.auth_permissions where code like'financial.payment.%'or code like'financial.settlement.%'or code in('financial.destination.manage','financial.payment_method.manage','financial.reconciliation.manage');insert into public.res_users_groups(tenant_id,user_id,group_id)values(c.tenant_id,c.owner_id,gid);insert into p9_r values(r.*);end$$;

select set_config('request.jwt.claim.sub',owner_auth::text,true)from p9_context;set local role authenticated;
do $$declare c p9_context%rowtype;r p9_r%rowtype;x jsonb;begin select*into c from p9_context;select*into r from p9_r;x:=public.create_and_provision_money_destination(c.tenant_id,'p9_bank','P9 Bank','bank',r.branch,null,null,'P9 Bank','P9 Runtime',null,'{}',true);r.bank_destination:=(x->>'destination_id')::uuid;r.bank_account:=(x->>'account_id')::uuid;r.config:=public.configure_payment_method_settlement(c.tenant_id,r.method,r.clearing,r.clearing_journal,r.fee,'bank',r.branch,true);update p9_r set bank_destination=r.bank_destination,bank_account=r.bank_account,config=r.config;end$$;

-- Canonical card payments: first one also proves customer allocation happens before provider settlement.
do $$declare c p9_context%rowtype;r p9_r%rowtype;x jsonb;i int;pid uuid;line uuid;mid uuid;invoice_line_id uuid;begin select*into c from p9_context;select*into r from p9_r;for i in 1..5 loop x:=public.create_financial_payment(c.tenant_id,'inbound',case i when 1 then 10000 when 2 then 10000 when 3 then 5000 when 4 then 3000 else 2000 end,r.method,'p9-pay-'||i,null,'EGP',r.customer,r.branch,'CARD-'||i);pid:=(x->>'payment_id')::uuid;perform public.submit_financial_payment(c.tenant_id,pid);perform public.confirm_financial_payment(c.tenant_id,pid);x:=public.post_financial_payment(c.tenant_id,pid,'inbound_customer_unallocated');mid:=(x->>'account_move_id')::uuid;select id into line from public.account_move_lines where move_id=mid and account_id=r.clearing;if line is null or(select amount_residual from public.account_move_lines where id=line)<>(case i when 1 then 10000 when 2 then 10000 when 3 then 5000 when 4 then 3000 else 2000 end)then raise exception'CARD_CLEARING_POST_INVALID';end if;if i=1 then r.p1:=pid;r.l1:=line;elsif i=2 then r.p2:=pid;r.l2:=line;elsif i=3 then r.p3:=pid;r.l3:=line;elsif i=4 then r.p4:=pid;r.l4:=line;else r.p5:=pid;r.l5:=line;end if;end loop;
 mid:=gen_random_uuid();insert into public.account_moves(id,tenant_id,branch_id,journal_id,name,move_type,partner_id,invoice_date,date,amount_total,state,ref,currency_code,created_by)values(mid,c.tenant_id,r.branch,r.clearing_journal,'P9 INVOICE','journal',r.customer,current_date,current_date,10000,'posted','p9_invoice','EGP',c.owner_id);insert into public.account_move_lines(tenant_id,move_id,account_id,partner_id,label,quantity,unit_price,debit,credit,line_type,is_reconciled,amount_residual,amount_residual_currency,parent_state,currency_code,created_by)values(c.tenant_id,mid,r.ar,r.customer,'Invoice AR',1,10000,10000,0,'open_item',false,10000,10000,'posted','EGP',c.owner_id)returning id into invoice_line_id;insert into public.account_move_lines(tenant_id,move_id,account_id,label,quantity,unit_price,debit,credit,line_type,is_reconciled,amount_residual,amount_residual_currency,parent_state,currency_code,created_by)values(c.tenant_id,mid,r.revenue,'Revenue',1,10000,0,10000,'other',true,0,0,'posted','EGP',c.owner_id);perform public.allocate_financial_payment(c.tenant_id,r.p1,invoice_line_id,10000,'p9-allocation');if(select amount_residual from public.account_move_lines where id=invoice_line_id)<>0 then raise exception'CARD_PAYMENT_ALLOCATION_INVALID';end if;update p9_r set p1=r.p1,l1=r.l1,p2=r.p2,l2=r.l2,p3=r.p3,l3=r.l3,p4=r.p4,l4=r.l4,p5=r.p5,l5=r.l5,invoice_line=invoice_line_id;end$$;

-- Full settlement with fee, partial settlement, then one three-payment batch.
do $$declare c p9_context%rowtype;r p9_r%rowtype;x jsonb;eligibility jsonb;sid uuid;full_sid uuid;partial_sid uuid;second_sid uuid;batch_sid uuid;mid uuid;rev_mid uuid;bank0 numeric;payment_count bigint;transfer_count bigint;begin select*into c from p9_context;select*into r from p9_r;select coalesce(sum(debit-credit),0)into bank0 from public.account_move_lines where account_id=r.bank_account;select count(*)into payment_count from public.financial_payments;select count(*)into transfer_count from public.financial_internal_transfers;
 eligibility:=public.get_financial_settlement_eligibility(c.tenant_id,r.method,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l1,'amount',10000)),r.bank_destination,10000,150,9850,'EGP',r.branch);if not coalesce((eligibility->>'eligible')::boolean,false)then raise exception'VALID_SETTLEMENT_REPORTED_INELIGIBLE: %',eligibility;end if;
 x:=public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l1,'amount',10000)),10000,150,9850,'EGP',current_date,'p9-full',r.branch,'FULL','PROVIDER-1');full_sid:=(x->>'settlement_id')::uuid;update p9_r set reversal_target=full_sid;perform public.submit_financial_settlement(c.tenant_id,full_sid);perform public.confirm_financial_settlement(c.tenant_id,full_sid);x:=public.post_financial_settlement(c.tenant_id,full_sid,'p9-full-post');mid:=(x->>'account_move_id')::uuid;if(select amount_residual from public.account_move_lines where id=r.l1)<>0 or not exists(select 1 from public.account_move_lines where move_id=mid and account_id=r.bank_account and debit=9850)or not exists(select 1 from public.account_move_lines where move_id=mid and account_id=r.fee and debit=150)then raise exception'FULL_SETTLEMENT_INVALID';end if;eligibility:=public.get_financial_settlement_reversal_eligibility(c.tenant_id,full_sid,current_date);if not(eligibility->>'eligible')::boolean then raise exception'SETTLEMENT_REVERSAL_ELIGIBILITY_MISMATCH: %',eligibility;end if;x:=public.reverse_financial_settlement_accounting(c.tenant_id,full_sid,'Wrong full settlement','p9-reverse-full',current_date);rev_mid:=(x->>'reversal_move_id')::uuid;if(select amount_residual from public.account_move_lines where id=r.l1)<>10000 or not exists(select 1 from public.account_move_lines where move_id=rev_mid and account_id=r.bank_account and credit=9850)or not exists(select 1 from public.account_move_lines where move_id=rev_mid and account_id=r.fee and credit=150)then raise exception'FULL_FEE_SETTLEMENT_REVERSAL_INVALID';end if;x:=public.reverse_financial_settlement_accounting(c.tenant_id,full_sid,'Wrong full settlement','p9-reverse-full',current_date);if not(x->>'idempotent_replay')::boolean then raise exception'SETTLEMENT_REVERSAL_REPLAY_FAILED';end if;begin perform public.reverse_financial_settlement_accounting(c.tenant_id,full_sid,'Wrong full settlement','p9-reverse-full-new-key',current_date);raise exception'SECOND_SETTLEMENT_REVERSAL_ACCEPTED';exception when check_violation or insufficient_privilege then null;end;
 x:=public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',6000)),6000,0,6000,'EGP',current_date,'p9-partial',r.branch);partial_sid:=(x->>'settlement_id')::uuid;perform public.submit_financial_settlement(c.tenant_id,partial_sid);perform public.confirm_financial_settlement(c.tenant_id,partial_sid);perform public.post_financial_settlement(c.tenant_id,partial_sid,'p9-partial-post');if(select amount_residual from public.account_move_lines where id=r.l2)<>4000 then raise exception'PARTIAL_SETTLEMENT_INVALID';end if;x:=public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',4000)),4000,0,4000,'EGP',current_date,'p9-second',r.branch);second_sid:=(x->>'settlement_id')::uuid;perform public.submit_financial_settlement(c.tenant_id,second_sid);perform public.confirm_financial_settlement(c.tenant_id,second_sid);perform public.post_financial_settlement(c.tenant_id,second_sid,'p9-second-post');perform public.reverse_financial_settlement_accounting(c.tenant_id,partial_sid,'Reverse first independent settlement','p9-reverse-partial',current_date);if(select amount_residual from public.account_move_lines where id=r.l2)<>6000 or(select accounting_state from public.financial_settlements where id=second_sid)<>'posted'then raise exception'MULTIPLE_SETTLEMENT_INDEPENDENT_REVERSAL_INVALID';end if;perform public.reverse_financial_settlement_accounting(c.tenant_id,second_sid,'Reverse second settlement','p9-reverse-second',current_date);if(select amount_residual from public.account_move_lines where id=r.l2)<>10000 then raise exception'PARTIAL_SETTLEMENT_REVERSAL_INVALID';end if;
 x:=public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l3,'amount',5000),jsonb_build_object('clearing_line_id',r.l4,'amount',3000),jsonb_build_object('clearing_line_id',r.l5,'amount',2000)),10000,100,9900,'EGP',current_date,'p9-batch',r.branch);batch_sid:=(x->>'settlement_id')::uuid;perform public.submit_financial_settlement(c.tenant_id,batch_sid);perform public.confirm_financial_settlement(c.tenant_id,batch_sid);perform public.post_financial_settlement(c.tenant_id,batch_sid,'p9-batch-post');if exists(select 1 from public.account_move_lines where id in(r.l3,r.l4,r.l5)and amount_residual<>0)then raise exception'BATCH_SETTLEMENT_INVALID';end if;perform public.reverse_financial_settlement_accounting(c.tenant_id,batch_sid,'Reverse batch settlement','p9-reverse-batch',current_date);if exists(select 1 from public.account_move_lines where(id=r.l3 and amount_residual<>5000)or(id=r.l4 and amount_residual<>3000)or(id=r.l5 and amount_residual<>2000))then raise exception'BATCH_SETTLEMENT_REVERSAL_INVALID';end if;
 eligibility:=public.get_financial_settlement_eligibility(c.tenant_id,r.method,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',11000)),r.bank_destination,11000,0,11000,'EGP',r.branch);if coalesce((eligibility->>'eligible')::boolean,false)then raise exception'OVER_RESIDUAL_REPORTED_ELIGIBLE';end if;begin perform public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',11000)),11000,0,11000,'EGP',current_date,'p9-over',r.branch);raise exception'OVER_SETTLEMENT_ACCEPTED';exception when check_violation then null;end;eligibility:=public.get_financial_settlement_eligibility(c.tenant_id,r.method,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',1000)),r.bank_destination,1000,100,800,'EGP',r.branch);if coalesce((eligibility->>'eligible')::boolean,false)then raise exception'AMOUNT_MISMATCH_REPORTED_ELIGIBLE';end if;begin perform public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',1000)),1000,100,800,'EGP',current_date,'p9-mismatch',r.branch);raise exception'FEE_MISMATCH_ACCEPTED';exception when check_violation then null;end;
 if(select count(*)from public.financial_settlements where tenant_id=c.tenant_id and idempotency_key like'p9-%')<>4 or(select count(distinct settlement_number)from public.financial_settlements where tenant_id=c.tenant_id and idempotency_key like'p9-%')<>4 or(select max(right(settlement_number,6)::int)-min(right(settlement_number,6)::int)from public.financial_settlements where tenant_id=c.tenant_id and idempotency_key like'p9-%')<>3 then raise exception'SETTLEMENT_NUMBER_SEQUENCE_NOT_UNIQUE_MONOTONIC';end if;if(select count(*)from public.financial_payments)<>payment_count or(select count(*)from public.financial_internal_transfers)<>transfer_count then raise exception'SETTLEMENT_CREATED_PAYMENT_OR_TRANSFER';end if;if(select status from public.financial_payments where id=r.p1)<>'confirmed'or(select accounting_state from public.financial_payments where id=r.p1)<>'posted'or(select amount_residual from public.account_move_lines where id=r.invoice_line)<>0 then raise exception'SETTLEMENT_REVERSAL_TOUCHED_CUSTOMER_ACCOUNTING';end if;end$$;

-- Unauthorized and direct paths fail closed.
select set_config('request.jwt.claim.sub',other_auth::text,true)from p9_context;set local role authenticated;
do $$declare c p9_context%rowtype;r p9_r%rowtype;blocked boolean:=false;target_settlement uuid;foreign_tenant uuid;begin select*into c from p9_context;select*into r from p9_r;target_settlement:=r.reversal_target;begin perform public.create_financial_settlement(c.tenant_id,r.method,r.bank_destination,jsonb_build_array(jsonb_build_object('clearing_line_id',r.l2,'amount',1)),1,0,1,'EGP',current_date,'p9-unauth',r.branch);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception'UNAUTHORIZED_SETTLEMENT_ACCEPTED';end if;blocked:=false;begin perform public.reverse_financial_settlement_accounting(c.tenant_id,target_settlement,'Unauthorized reversal','p9-unauthorized-reversal',current_date);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception'UNAUTHORIZED_SETTLEMENT_REVERSAL_ACCEPTED';end if;select tenant_id into foreign_tenant from public.tenant_users where tenant_id<>c.tenant_id limit 1;blocked:=false;begin perform public.get_financial_settlement_reversal_eligibility(foreign_tenant,target_settlement,current_date);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception'CROSS_TENANT_SETTLEMENT_REVERSAL_ACCEPTED';end if;blocked:=false;begin insert into public.financial_settlements(tenant_id,settlement_number,payment_method_id,settlement_config_id,money_destination_id,gross_amount,fees_amount,net_amount,currency_code,settlement_date,created_by,idempotency_key,request_fingerprint)values(c.tenant_id,'STL-2026-999999',r.method,r.config,r.bank_destination,1,0,1,'EGP',current_date,c.other_id,'forged',repeat('f',64));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception'DIRECT_SETTLEMENT_INSERT_ACCEPTED';end if;blocked:=false;begin update public.financial_settlements set accounting_state='reversed'where tenant_id=c.tenant_id;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception'DIRECT_SETTLEMENT_UPDATE_ACCEPTED';end if;end$$;set local role postgres;

do $$declare b p9_before%rowtype;begin select*into b from p9_before;if exists(select 1 from public.account_moves m join public.account_move_lines l on l.move_id=m.id and l.tenant_id=m.tenant_id where m.state='posted'group by m.id having round(sum(l.debit-l.credit),2)<>0)then raise exception'UNBALANCED_POSTED_MOVE';end if;raise notice'PHASE9_BASELINE payments=% refunds=% settlements=% items=% moves=% lines=% partials=% debit=% credit=%',b.payments,b.refunds,b.settlements,b.items,b.moves,b.lines,b.partials,b.debit,b.credit;end$$;
rollback;
